"""Local system-virtual-model wearing-image workbench."""

WEAR_PAGE = """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>上手图与佩戴图</title><style>
body{font-family:system-ui,"PingFang SC",sans-serif;background:#f6f2ec;color:#29231f;margin:0}.wrap{max-width:920px;margin:auto;padding:36px 20px}.panel{background:#fff;border:1px solid #e2d9ce;border-radius:16px;padding:20px;margin:14px 0}.notice{background:#fff6df;border-color:#e7ce98}.grid,.results{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px}.item{border:1px solid #e2d9ce;border-radius:12px;padding:11px}.item img{width:100%;aspect-ratio:1;object-fit:contain;background:#f7f4ef;border-radius:9px}button{padding:10px 13px;border:0;border-radius:9px;background:#29231f;color:#fff;cursor:pointer;margin:4px}input,select{padding:9px;border:1px solid #d8cec2;border-radius:8px}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}.fields label{display:grid;gap:5px}.muted{color:#746b63}.ok{color:#246b49;font-weight:700}.error{color:#a33}
</style></head><body><main class="wrap"><p><a href="/local/style-suite/output-center">← 返回内容输出中心</a></p><h1>上手图 / 佩戴图</h1><section class="panel notice"><strong>身份标识：</strong>本工作台只生成“系统虚拟模特”候选，绝不是商品真人实拍。商品必须完整、可数、无遮挡；未开放真人人物档案。</section><section class="panel"><label>客户ID <input id="customer" size="38"></label><button id="load">读取我的商品库</button><p id="status" class="muted">先读取已确认商品。</p><div id="assets" class="grid"></div></section><section id="settings" class="panel" hidden><div class="fields"><label>佩戴位置<select id="position"><option value="auto">按商品自动选择</option><option value="hand">手部</option><option value="wrist">手腕</option><option value="neck">颈部</option><option value="ear">耳部</option><option value="garment">衣物</option></select></label><label>肤色呈现<select id="skin"><option value="light">浅</option><option value="medium" selected>中</option><option value="deep">深</option></select></label><label>性别呈现<select id="gender"><option value="feminine">偏女性</option><option value="masculine">偏男性</option><option value="neutral" selected>中性</option></select></label><label>年龄感<select id="age"><option value="adult">成年</option><option value="mature">成熟</option></select></label><label>整体风格<select id="styling"><option value="minimal">极简</option><option value="commercial" selected>商业</option><option value="elegant">优雅</option><option value="casual">日常</option></select></label><label>佩戴场景风格<select id="style"></select></label></div><button id="generate">生成 3 张虚拟佩戴候选</button></section><section id="result-panel" class="panel" hidden><h2>候选审核</h2><p class="notice">以下均为系统虚拟模特，不是真人实拍，也不可直接发布。</p><div id="results" class="results"></div></section></main><script>
const customer=document.querySelector('#customer'),load=document.querySelector('#load'),assets=document.querySelector('#assets'),statusNode=document.querySelector('#status'),settings=document.querySelector('#settings'),style=document.querySelector('#style'),generate=document.querySelector('#generate'),resultPanel=document.querySelector('#result-panel'),results=document.querySelector('#results');const params=new URLSearchParams(location.search);customer.value=params.get('benchmark_customer_id')||localStorage.getItem('style-suite-customer-id')||'';let library=[],selectedAsset,plan;
const headers=()=>({'X-Customer-Id':customer.value.trim()});async function json(url,options={}){const response=await fetch(url,{...options,headers:{...headers(),...(options.headers||{})}}),body=await response.json();if(!response.ok)throw Error(body.error?.code||`HTTP_${response.status}`);return body}
load.onclick=async()=>{assets.replaceChildren();settings.hidden=true;resultPanel.hidden=true;try{library=await json('/local/style-suite/api/multi-product/options');statusNode.textContent=library.length?'选择一件商品。':'商品库暂无已确认且已授权转换的商品。';for(const x of library){const card=document.createElement('article');card.className='item';card.innerHTML=`<img alt="${x.product_id}"><p>${x.product_id}</p><button>选择</button>`;assets.append(card);card.querySelector('button').onclick=()=>choose(x);const response=await fetch(x.content_url,{headers:headers()}),blob=await response.blob();card.querySelector('img').src=URL.createObjectURL(blob)}}catch(error){statusNode.className='error';statusNode.textContent='读取失败：'+error.message}};
async function choose(asset){selectedAsset=asset;settings.hidden=true;try{plan=await json('/v1/style-suites/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:asset.product_id,source_asset_id:asset.asset_id})});const items=plan.items.filter(x=>x.slot_key==='wear');style.replaceChildren();for(const item of items){const option=document.createElement('option');option.value=JSON.stringify(item);option.textContent=`${item.style_name} · 佩戴`;style.append(option)}settings.hidden=!items.length;statusNode.textContent=items.length?'商品已选，请确认虚拟模特呈现。':'该客户尚未确认“佩戴”套图位置，请先在商品图工作台为风格勾选佩戴。'}catch(error){statusNode.className='error';statusNode.textContent='风格准备失败：'+error.message}}
generate.onclick=async()=>{const item=JSON.parse(style.value),ratio=item.slot_snapshot.rules.aspect_ratio||'4:5';generate.disabled=true;results.replaceChildren();try{const profile={position:document.querySelector('#position').value,skin_tone:document.querySelector('#skin').value,gender_presentation:document.querySelector('#gender').value,age_presentation:document.querySelector('#age').value,styling:document.querySelector('#styling').value},job=await json('/v1/image-outputs/wear',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sources:[{product_id:selectedAsset.product_id,asset_id:selectedAsset.asset_id}],scene_style_id:item.scene_style_id,style_card_version_id:item.scene_style_version_id,output_ratio:ratio,slot_key:'wear',wear_presentation:profile,idempotency_key:`browser-wear-${crypto.randomUUID()}`})}),gate=await json(`/v1/image-outputs/${job.id}/authenticity-checks`,{method:'POST'});if(job.presentation_origin!=='system_virtual_model'||job.real_wear_photo!==false)throw Error('wear_identity_label_missing');resultPanel.hidden=false;for(const candidate of gate.candidates){const card=document.createElement('article');card.className='item';card.innerHTML=`<img alt="虚拟佩戴候选 ${candidate.sequence_number}"><p>系统虚拟模特 · ${candidate.candidate_state}</p><button data-decision="approved">采用</button><button data-decision="rejected">退回</button>`;results.append(card);const response=await fetch(`/local/style-suite/api/reviewable-image-jobs/${job.id}/candidates/${candidate.id}/content`,{headers:headers()}),blob=await response.blob();card.querySelector('img').src=URL.createObjectURL(blob);for(const button of card.querySelectorAll('button'))button.onclick=()=>review(job.id,candidate.id,button.dataset.decision,card)}statusNode.className='ok';statusNode.textContent='已生成并完成本地规则检查；仍需人工审核。'}catch(error){statusNode.className='error';statusNode.textContent='生成停止：'+error.message}finally{generate.disabled=false}};
async function review(jobId,candidateId,decision,card){try{const outcome=await json(`/v1/image-outputs/${jobId}/candidates/${candidateId}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision,idempotency_key:`browser-wear-review-${jobId}-${candidateId}-${decision}`,fidelity_warning_acknowledged:false})});card.querySelectorAll('button').forEach(x=>x.disabled=true);const p=document.createElement('p');p.className='ok';p.textContent=outcome.customer_approved?'✓ 已人工采用；仍不可直接发布':'已退回并保留记录';card.append(p)}catch(error){statusNode.className='error';statusNode.textContent='审核保存失败：'+error.message}}
</script></body></html>"""
